function SumEvenAtOddIndices(lst: seq<int>): int
    reads lst
{
    var total := 0;
    var length := |lst|;
    for i := 1 to length - 1 by 2 // iterate over odd indices
        if lst[i] % 2 == 0 // check if the element is even
        {
            total := total + lst[i]; // add it to total
        }
    total
}
